"""Actual app routes/controller early refusal; no database, browser, or executor."""
import json,subprocess,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
SETUP=r'''require$argv[1].'/support/runtime/src/__phutil_library_init__.php';phutil_load_library($argv[1].'/src');
$stack=new PhabricatorConfigStackSource();$stack->pushSource(new PhabricatorConfigDefaultSource());
$source=new PhabricatorConfigDictionarySource(array('phabricator.cache-namespace'=>'media-admission-unit','phabricator.base-uri'=>'https://app.example.com/','security.alternate-file-domain'=>'https://files.example.com/','governance.media-exchange.enabled'=>true,'governance.media-exchange.http-enabled'=>true));$stack->pushSource($source);
(new ReflectionProperty(PhabricatorEnv::class,'sourceStack'))->setValue(null,$stack);(new ReflectionProperty(PhabricatorEnv::class,'cache'))->setValue(null,array());
function media_admission_routes(){ $app=new PhabricatorAuthApplication();return(new AphrontRoutingMap())->setSite(new PhabricatorPlatformSite())->setApplication($app)->setRoutes($app->getRoutes()); }
function media_admission_request($action,$viewer){ $_SERVER['HTTPS']='on';$_SERVER['REQUEST_METHOD']=$action==='issue'?'POST':'GET';$_SERVER['HTTP_ORIGIN']='https://app.example.com';$_SERVER['HTTP_SEC_FETCH_SITE']='same-origin';$_SERVER['CONTENT_TYPE']='application/x-www-form-urlencoded';$path='/auth/media/'.$action.'/';$match=media_admission_routes()->routePath($path);if(!$match||!($match->getController()instanceof PhorgeGovernanceMediaAuthorizeController)){throw new RuntimeException('actual_media_route_required');}$request=(new AphrontRequest('app.example.com',$path))->setUser($viewer)->setURIMap($match->getURIData())->setRequestData(array('path'=>'/file/data/key/PHID-FILE-aaaaaaaaaaaaaaaaaaaa/unit.png','payload'=>json_encode(array('transaction'=>str_repeat('a',64),'client_nonce'=>str_repeat('b',64),'path'=>'/file/data/key/PHID-FILE-aaaaaaaaaaaaaaaaaaaa/unit.png'))));return array($request,$match->getController()); }
function media_admission_denied($action,$viewer){list($request,$controller)=media_admission_request($action,$viewer);$transport=PhorgeGovernanceMediaHTTPProtocol::assertRequest($request,'app',$action==='issue');$early=false;try{PhorgeGovernanceNativeActorContext::newFromWebRequest($request);}catch(RuntimeException$error){$early=$error->getMessage()==='governance_web_credential_required';}if(!$early){throw new RuntimeException('early_native_credential_refusal_required');}$response=$controller->setRequest($request)->handleRequest($request);$headers=$response->getHeaders();return array('status'=>$response->getHTTPResponseCode(),'body'=>json_decode($response->buildResponseString(),true),'early_native_credential_refusal'=>$early,'transport_preconditions'=>$transport===array('app'=>'https://app.example.com','files'=>'https://files.example.com'),'cookies'=>count(array_filter($headers,static fn($h)=>$h[0]==='Set-Cookie')),'no_SQL_connection_registered'=>(new ReflectionProperty(LiskDAO::class,'connections'))->getValue()===array(),'bootstrap'=>PhorgeGovernanceMediaHTTPProtocol::pageBootstrapConfig($action==='authorize'?$request:media_admission_request('authorize',$viewer)[0]));}
'''
class MediaAppSessionAdmissionTest(unittest.TestCase):
 def php(self,body):
  p=subprocess.run(['php','-r',SETUP+body,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');return json.loads(p.stdout)
 def assert_denied(self,rows):
  for row in rows:
   self.assertEqual(row,dict(status=403,body={'error':'media_request_unavailable'},early_native_credential_refusal=True,transport_preconditions=True,cookies=0,no_SQL_connection_registered=True,bootstrap=None))
 def test_actual_native_routes_require_explicit_HTTP_feature_and_dispatch_real_controller(self):
  d=self.php("$out=array();foreach(array(false,true)as$enabled){$source->setKeys(array('governance.media-exchange.http-enabled'=>$enabled));(new ReflectionProperty(PhabricatorEnv::class,'cache'))->setValue(null,array());$map=media_admission_routes();foreach(array('authorize','issue')as$action){$route=$map->routePath('/auth/media/'.$action.'/');$out[]=$enabled?($route!==null&&$route->getController()instanceof PhorgeGovernanceMediaAuthorizeController&&$route->getURIData()['mediaAction']===$action):$route===null;}}echo json_encode($out);")
  self.assertEqual(d,[True]*4)
 def test_media_only_cookies_never_replace_native_application_session(self):
  self.assert_denied(self.php("$_COOKIE=array(PhorgeGovernanceMediaHTTPProtocol::CREDENTIAL_COOKIE=>str_repeat('c',64),PhorgeGovernanceMediaHTTPProtocol::BROWSER_COOKIE=>str_repeat('d',64));$_SERVER['HTTP_COOKIE']='__Host-phorge-media='.str_repeat('c',64);$out=array();foreach(array('authorize','issue')as$action){$out[]=media_admission_denied($action,new PhabricatorUser());}echo json_encode($out);"))
 def test_deleted_or_missing_native_cookie_rejects_even_attached_unsaved_session_metadata(self):
  # Deliberately unsaved metadata is a negative admission collaborator, never a
  # claimed valid/native login. No valid session digest/HMAC/SQL path is entered.
  self.assert_denied(self.php("$viewer=(new PhabricatorUser())->setID(1)->setPHID('PHID-USER-'.str_repeat('a',20));$viewer->attachSession((new PhabricatorAuthSession())->setUserPHID($viewer->getPHID())->setType(PhabricatorAuthSession::TYPE_WEB)->setIsPartial(0));$out=array();foreach(array(null,'deleted')as$cookie){$_COOKIE=$cookie===null?array():array(PhabricatorCookies::COOKIE_SESSION=>$cookie);$probe=new AphrontRequest('app.example.com','/auth/media/authorize/');if($probe->getCookie(PhabricatorCookies::COOKIE_SESSION)!==null){throw new RuntimeException('actual_missing_or_deleted_cookie_normalization_required');}foreach(array('authorize','issue')as$action){$out[]=media_admission_denied($action,$viewer);}}echo json_encode($out);"))
 def test_attached_other_user_metadata_cannot_bypass_anonymous_or_unknown_token_kind(self):
  self.assert_denied(self.php("$viewer=(new PhabricatorUser())->setID(2)->setPHID('PHID-USER-'.str_repeat('b',20));$viewer->attachSession((new PhabricatorAuthSession())->setUserPHID('PHID-USER-'.str_repeat('a',20))->setType(PhabricatorAuthSession::TYPE_WEB)->setIsPartial(0));$out=array();foreach(array('A/'.str_repeat('a',64),'INVALID/'.str_repeat('b',64))as$cookie){$_COOKIE=array(PhabricatorCookies::COOKIE_SESSION=>$cookie,PhorgeGovernanceMediaHTTPProtocol::CREDENTIAL_COOKIE=>str_repeat('c',64));foreach(array('authorize','issue')as$action){$out[]=media_admission_denied($action,$viewer);}}echo json_encode($out);"))
if __name__=='__main__':unittest.main()
